 let parallel=document(&compiled,r#"article ja "対応" body cons paragraph cons parallel cons variant ja "" cons variant en "EN" cons variant fr "FR" nil nil nil"#)?;
 let select=|language:&str,fallbacks:Vec<String>|options(ParallelMode::Single{language:language.into(),fallbacks});
 let en=output(&parallel,&select("de",vec!["EN".into(),"fr".into()]),r)?;assert!(en.contains(">EN<")&&!en.contains(">FR<"));let fr=output(&parallel,&select("de",vec!["fr".into(),"en".into()]),r)?;assert!(fr.contains(">FR<")&&!fr.contains(">EN<"));let ja=output(&parallel,&select("JA",vec![]),r)?;assert!(ja.contains("lang=\"ja\"><span></span>")&&!ja.contains(">EN<"));assert!(output(&parallel,&select("de",vec![]),r).is_err());
 for mode in [ParallelMode::Rows,ParallelMode::Columns]{let out=output(&parallel,&options(mode.clone()),r)?;assert!(out.find(">EN<")<out.find(">FR<"));assert!(out.contains(match mode{ParallelMode::Rows=>"nepl-parallel-rows",_=>"nepl-parallel-columns"}));}
